import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict with side, price, qty, seq, active
    buy_heap = []  # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0

    def clean_heap_top(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            break

    def match_incoming(side, price, qty, is_market):
        # price is None if market order (any price)
        nonlocal trades
        remaining = qty
        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            clean_heap_top(opp_heap)
            if not opp_heap:
                break
            top = opp_heap[0]
            oid = top[2]
            info = book[oid]
            resting_price = info['price']

            if not is_market:
                if side == 'buy':
                    if resting_price > price:
                        break
                else:
                    if resting_price < price:
                        break

            heapq.heappop(opp_heap)
            trade_qty = min(remaining, info['qty'])
            if side == 'buy':
                trades.append([None, oid, resting_price, trade_qty])
            else:
                trades.append([oid, None, resting_price, trade_qty])

            info['qty'] -= trade_qty
            remaining -= trade_qty

            if info['qty'] > 0:
                # push back
                heapq.heappush(opp_heap, top)
            else:
                info['active'] = False

        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, is_market=False)
